PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT ?house ?successionMethod
WHERE {
  ?monarch wdt:P350 wd:Q402278;
          wdt:P1344 ?house;
          wdt:P1000 ?start;
          wdt:P2277 ?successionMethod.

  {
    SELECT ?house (MIN(?start) AS ?minStart)
    WHERE {
      ?otherMonarch wdt:P350 wd:Q402278;
                  wdt:P1344 ?house;
                  wdt:P1000 ?start.
    }
    GROUP BY ?house
  }
  FILTER (?start = ?minStart)
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT ?house ?method
WHERE {
  ?monarch wdt:P17 wd:Q22 ;  # England (country entity)
          wdt:P1344 ?house ;
          wdt:P1000 ?start ;
          wdt:P2277 ?method .
  FILTER NOT EXISTS {
    ?otherMonarch wdt:P17 wd:Q22 ;
                wdt:P1344 ?house ;
                wdt:P1000 ?otherStart .
    FILTER (?otherStart < ?start)
  }
}

